export const tokensCss = "/*\n * Design tokens: the source of the default values.\n *\n * Components don't depend on this file. When @imdz/react is built\n * (its scripts/build.mjs), every var(--imdz-x) in a component's CSS\n * becomes var(--imdz-x, value) with the value from here, so each\n * component works on its own and anyone can override any token in :root.\n *\n * The palette is monochrome: black, white and grays. Color only shows up in\n * states (success, warning, error).\n *\n * light-dark(light, dark): the store website and the Web Components load\n * this file as is and follow the page's color-scheme. In the published\n * package, the build keeps only the light value and moves the dark one to\n * dist/dark.css.\n */\n:where(:root) {\n  /* The @font-face rules are in fonts.css; the components put them on the\n     page themselves. */\n  --imdz-font: \"imdz Inter\", system-ui, -apple-system, \"Segoe UI\", Roboto,\n    sans-serif;\n  --imdz-font-mono: \"imdz JetBrains Mono\", ui-monospace, \"SF Mono\", Menlo,\n    Consolas, monospace;\n  --imdz-radius: 0px;\n  --imdz-tracking: 0.08em;\n\n  --imdz-bg: light-dark(#ffffff, #000000);\n  --imdz-surface: light-dark(#f2f2f2, #0d0d0d);\n  --imdz-border: light-dark(#c4c4c4, #2e2e2e);\n  --imdz-text: light-dark(#000000, #ffffff);\n  --imdz-muted: light-dark(#5e5e5e, #9a9a9a);\n\n  --imdz-primary: var(--imdz-text);\n  --imdz-on-primary: var(--imdz-bg);\n  --imdz-success: light-dark(#0f7a3d, #5dffa0);\n  --imdz-warning: light-dark(#8f5a00, #ffd166);\n  --imdz-danger: light-dark(#c4001a, #ff5c6c);\n  --imdz-on-danger: light-dark(#ffffff, #000000);\n\n  --imdz-focus: var(--imdz-text);\n}\n\n:where([data-imdz-theme=\"light\"]) {\n  color-scheme: light;\n}\n\n:where([data-imdz-theme=\"dark\"]) {\n  color-scheme: dark;\n}\n";
export const tooltipCss = ".tooltip {\n  position: relative;\n  display: inline-flex;\n}\n\n.bubble {\n  position: absolute;\n  bottom: calc(100% + 0.5rem);\n  left: 50%;\n  z-index: 10;\n  padding: 0.375rem 0.5rem;\n  border-radius: var(--imdz-radius);\n  background: var(--imdz-text);\n  color: var(--imdz-bg);\n  font: 600 0.6875rem/1.2 var(--imdz-font-mono);\n  letter-spacing: var(--imdz-tracking);\n  text-transform: uppercase;\n  white-space: nowrap;\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n  translate: -50% 0.25rem;\n  transition: opacity 120ms, translate 120ms, visibility 120ms;\n}\n\n/* Shows on hover and also on keyboard focus. */\n.tooltip:hover .bubble,\n.tooltip:focus-within .bubble {\n  opacity: 1;\n  visibility: visible;\n  translate: -50% 0;\n}\n";
